-- Desabilitar verificação de chaves estrangeiras temporariamente para o TRUNCATE
SET FOREIGN_KEY_CHECKS = 0;

-- Apagar todos os registros das tabelas BPO
TRUNCATE TABLE subscription_charges;
TRUNCATE TABLE subscriptions;
TRUNCATE TABLE excluded_asaas_charges;

-- Reabilitar verificação de chaves estrangeiras
SET FOREIGN_KEY_CHECKS = 1;

-- Confirmar que as tabelas estão vazias
SELECT 'subscription_charges' as tabela, COUNT(*) as registros FROM subscription_charges
UNION ALL
SELECT 'subscriptions', COUNT(*) FROM subscriptions
UNION ALL
SELECT 'excluded_asaas_charges', COUNT(*) FROM excluded_asaas_charges;

